1	import { useState } from 'react';
2	import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
3	import { getJson, postJson } from '../../api/http';
4	import { asString, useSearchParam } from '../../url/useSearchParam';
5	import { ClientsToolbar } from '../../slots/defs/clientsToolbar';
6	import { ClientRowActions } from '../../slots/defs/clientRowActions';
7	
8	// A client as the server returns it.
9	export type Client = { id: number; name: string; email: string };
10	
11	// A client must carry a proper email address. Same shape the server enforces (ClientsPost) so the
12	// UI never asks the server to save what the server will reject.
13	export function isValidEmail(email: string): boolean {
14	  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim());
15	}
16	
17	// The clients page: the whole list of clients plus the form to add one. Server data is read with
18	// useQuery under the ['clients'] key and changed with useMutation + invalidateQueries — never
19	// copied into state, never hand-maintained. The only useState here is the two fields the user is
20	// currently typing into (rule 4).
21	export function ClientsPage() {
22	  const queryClient = useQueryClient();
23	  // The name filter lives in the URL (owned by features/clients/search.slot.tsx). The list reads
24	  // the same key and asks the server for the narrowed list, so it stays a single source of truth —
25	  // no server data copied into state. The key still starts with 'clients', so writes that
26	  // invalidateQueries({ queryKey: ['clients'] }) still refresh it.
27	  const [q] = useSearchParam('clientSearch', asString);
28	  const clients = useQuery({
29	    queryKey: ['clients', q],
30	    queryFn: () =>
31	      getJson<Client[]>(q ? `/api/clients?q=${encodeURIComponent(q)}` : '/api/clients'),
32	  });
33	
34	  const [name, setName] = useState('');
35	  const [email, setEmail] = useState('');
36	  const [emailError, setEmailError] = useState(false);
37	
38	  const create = useMutation({
39	    mutationFn: () => postJson<Client>('/api/clients', { name, email }),
40	    onSuccess: () => {
41	      setName('');
42	      setEmail('');
43	      setEmailError(false);
44	      void queryClient.invalidateQueries({ queryKey: ['clients'] });
45	    },
46	  });
47	
48	  const rows = clients.data ?? [];
49	
50	  return (
51	    <section data-testid="clients">
52	      <form
53	        data-testid="client-form"
54	        onSubmit={(e) => {
55	          e.preventDefault();
56	          if (!isValidEmail(email)) {
57	            setEmailError(true);
58	            return;
59	          }
60	          setEmailError(false);
61	          create.mutate();
62	        }}
63	      >
64	        <input
65	          data-testid="client-form-name"
66	          placeholder="Name"
67	          value={name}
68	          onChange={(e) => setName(e.target.value)}
69	        />
70	        <input
71	          data-testid="client-form-email"
72	          placeholder="Email"
73	          value={email}
74	          onChange={(e) => setEmail(e.target.value)}
75	        />
76	        {emailError && (
77	          <p data-testid="client-form-email-error" role="alert">
78	            Enter a valid email address.
79	          </p>
80	        )}
